class JavaElementImageDescriptor {
    public static final int ERROR = 0x1;
    public static final int WARNING = 0x2;
    public static final int PROJECT_ERROR = 0x2000;
}

class PackageExplorerProblemsDecorator {
    // In the 'before' state, this class may not define PROJECT_ERROR publicly,
    // but it needs to exist for the 'after' state's compilation.
}

public class MyClientCode {
    private static final int MY_PROJECT_ERROR = JavaElementImageDescriptor.PROJECT_ERROR;

    public int getStatus(int flags) {
        if ((flags & JavaElementImageDescriptor.PROJECT_ERROR) != 0) {
            return MY_PROJECT_ERROR;
        }
        return 0;
    }
}

